addCSS(`
.ds-ov{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;box-sizing:border-box;overflow:hidden;
 padding:max(10px,env(safe-area-inset-top)) max(10px,env(safe-area-inset-right)) max(10px,env(safe-area-inset-bottom)) max(10px,env(safe-area-inset-left));
 font-family:'Cinzel','Times New Roman',serif;color:#e8f0ff;-webkit-user-select:none;user-select:none;
 background:radial-gradient(ellipse at 50% 30%,rgba(27,47,107,.93) 0%,rgba(10,18,48,.95) 55%,rgba(4,7,15,.98) 100%);animation:dsFade .22s ease-out}
.ds-ov *{box-sizing:border-box}
.ds-ov::before,.ds-ov::after{content:'';position:absolute;left:0;right:0;top:0;height:200%;pointer-events:none;z-index:0;opacity:.75;
 background-image:radial-gradient(1.5px 1.5px at 8% 12%,#fff,transparent),radial-gradient(1px 1px at 22% 38%,#cfe2ff,transparent),radial-gradient(2px 2px at 35% 8%,rgba(255,226,150,.9),transparent),
 radial-gradient(1px 1px at 48% 27%,#fff,transparent),radial-gradient(1.5px 1.5px at 63% 44%,#bcd6ff,transparent),radial-gradient(1px 1px at 77% 16%,#fff,transparent),
 radial-gradient(2px 2px at 88% 35%,rgba(255,226,150,.85),transparent),radial-gradient(1px 1px at 14% 47%,#fff,transparent),radial-gradient(1.5px 1.5px at 56% 4%,#dbe8ff,transparent),
 radial-gradient(1px 1px at 93% 6%,#fff,transparent),radial-gradient(1px 1px at 4% 30%,#bcd6ff,transparent),radial-gradient(1.5px 1.5px at 70% 31%,#fff,transparent);
 background-size:100% 50%;animation:dsDrift 40s linear infinite}
.ds-ov::after{opacity:.45;background-size:70% 35%;animation-duration:26s;filter:blur(.4px)}
.ds-ov>*{position:relative;z-index:1}
@keyframes dsDrift{from{transform:translateY(0)}to{transform:translateY(-50%)}}
@keyframes dsFade{from{opacity:0}to{opacity:1}}
@keyframes dsBlink{0%,100%{opacity:.3}50%{opacity:1}}
@keyframes dsGlow{0%,100%{filter:drop-shadow(0 0 10px rgba(255,210,120,.45)) drop-shadow(0 0 26px rgba(90,150,255,.35))}50%{filter:drop-shadow(0 0 16px rgba(255,220,140,.7)) drop-shadow(0 0 40px rgba(110,170,255,.55))}}
@keyframes dsCur{0%,100%{transform:translateY(-50%) translateX(0)}50%{transform:translateY(-50%) translateX(2px)}}
.ds-panel{position:relative;width:min(900px,100%);max-height:100%;display:flex;flex-direction:column;border-radius:9px;
 background:linear-gradient(180deg,rgba(20,40,90,.92),rgba(8,16,44,.94));border:1px solid rgba(190,215,255,.6);
 box-shadow:inset 0 0 0 1px rgba(255,255,255,.06),inset 0 0 26px rgba(120,170,255,.18),0 12px 50px rgba(0,0,0,.6),0 0 0 3px rgba(4,8,22,.55);padding:14px 22px 10px}
.ds-head{position:relative;display:flex;align-items:center;justify-content:center;min-height:30px}
.ds-title{font-size:clamp(17px,2.4vw,25px);letter-spacing:.26em;padding-left:.26em;text-transform:uppercase;color:#f3d27a;text-align:center;font-weight:700;
 text-shadow:0 0 12px rgba(243,210,122,.4),0 2px 0 rgba(0,0,0,.5)}
.ds-x{position:absolute;right:-8px;top:50%;transform:translateY(-50%);width:34px;height:34px;display:flex;align-items:center;justify-content:center;border-radius:50%;
 color:#cfe0ff;font-size:17px;cursor:pointer;border:1px solid rgba(190,215,255,.35);background:rgba(10,20,50,.6);font-family:sans-serif}
.ds-x:hover{color:#f3d27a;border-color:#f3d27a}
.ds-line{height:1px;flex:0 0 1px;margin:8px 0;background:linear-gradient(90deg,transparent,rgba(190,215,255,.5) 18%,rgba(190,215,255,.5) 82%,transparent)}
.ds-tabs{display:flex;justify-content:center;gap:6px;overflow-x:auto;scrollbar-width:none;flex:0 0 auto;align-items:center;padding:2px}
.ds-tabs::-webkit-scrollbar{display:none}
.ds-tab{padding:5px 16px;font-size:clamp(11px,1.3vw,13px);letter-spacing:.16em;text-transform:uppercase;color:#9fb3d6;cursor:pointer;white-space:nowrap;
 border:1px solid rgba(190,215,255,.35);border-radius:999px;background:rgba(10,22,58,.6);font-weight:700}
.ds-tab:hover{color:#e8f0ff;border-color:rgba(190,215,255,.7)}
.ds-tab.on{color:#0b1636;background:linear-gradient(180deg,#ffe08a,#d9a93f);border-color:#ffe9a8;box-shadow:0 0 12px rgba(255,210,120,.45)}
.ds-tabkey{display:inline-block;padding:1px 7px;border:1px solid rgba(190,215,255,.45);border-radius:4px;color:#f3d27a;font-family:'EB Garamond',serif;font-size:12px;white-space:nowrap;background:rgba(4,8,22,.5)}
.ds-body{overflow-y:auto;overflow-x:hidden;flex:1 1 auto;min-height:0;padding:4px 2px;scrollbar-width:thin;scrollbar-color:rgba(190,215,255,.45) transparent;
 -webkit-overflow-scrolling:touch;touch-action:pan-y;overscroll-behavior:contain}
.ds-body::-webkit-scrollbar{width:6px}.ds-body::-webkit-scrollbar-thumb{background:rgba(190,215,255,.4);border-radius:3px}
.ds-row{display:flex;align-items:center;justify-content:space-between;gap:14px;min-height:36px;padding:2px 14px 2px 30px;margin:1px 0;position:relative;cursor:pointer;border-radius:5px;
 letter-spacing:.1em;text-transform:uppercase;font-size:clamp(12px,1.4vw,15px);color:#d6e2f8;font-weight:700;border:1px solid transparent}
.ds-row:nth-child(even){background:rgba(255,255,255,.025)}
.ds-row.sel{background:linear-gradient(90deg,rgba(80,170,255,.35),rgba(255,210,120,.25));border-color:rgba(190,215,255,.35);color:#fff;
 text-shadow:0 0 8px rgba(160,210,255,.6);box-shadow:inset 0 0 12px rgba(120,190,255,.15)}
.ds-row.sel::before{content:'◆';position:absolute;left:10px;top:50%;transform:translateY(-50%);color:#f3d27a;font-size:11px;text-shadow:0 0 8px rgba(255,210,120,.9);animation:dsCur 1s ease-in-out infinite}
.ds-row.dis{opacity:.4;cursor:default}
.ds-lab{flex:1 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis}
.ds-hdr{display:flex;align-items:center;margin:14px 0 6px;padding:5px 16px;color:#f3d27a;letter-spacing:.24em;font-size:clamp(11px,1.25vw,13px);text-transform:uppercase;font-weight:700;
 background:linear-gradient(90deg,rgba(243,210,122,.28),rgba(243,210,122,.08) 60%,transparent);border-left:3px solid #f3d27a;border-radius:0 3px 3px 0}
.ds-val{display:flex;align-items:center;gap:6px;color:#e8f0ff;white-space:nowrap;flex:0 0 auto}
.ds-arr{display:inline-flex;align-items:center;justify-content:center;width:28px;height:30px;color:rgba(190,215,255,.55);font-family:'EB Garamond',serif;font-size:22px;cursor:pointer;line-height:1}
.ds-row.sel .ds-arr{color:#f3d27a}.ds-arr:hover{color:#ffe08a!important}
.ds-vtx{min-width:clamp(90px,12vw,150px);text-align:center}
.ds-sl{position:relative;width:clamp(110px,17vw,210px);height:28px;touch-action:none;cursor:pointer}
.ds-sl i{position:absolute;left:0;right:0;top:50%;height:4px;margin-top:-2px;border-radius:2px;background:rgba(4,8,22,.7);box-shadow:inset 0 0 0 1px rgba(190,215,255,.3)}
.ds-sl b{position:absolute;left:0;top:50%;height:4px;margin-top:-2px;border-radius:2px;background:linear-gradient(90deg,#3d8be0,#9fd0ff 60%,#f3d27a)}
.ds-sl s{position:absolute;top:50%;width:11px;height:11px;margin:-5.5px 0 0 -5.5px;transform:rotate(45deg);background:linear-gradient(135deg,#fff3c4,#d9a93f);border:1px solid #fff6d8;box-shadow:0 0 8px rgba(255,210,120,.8);text-decoration:none}
.ds-num{min-width:46px;text-align:right;font-family:'EB Garamond',serif;font-size:1.08em;letter-spacing:.04em}
.ds-key,.ds-bt{min-width:clamp(70px,10vw,112px);padding:3px 10px;border:1px solid rgba(190,215,255,.35);border-radius:5px;text-align:center;cursor:pointer;
 font-family:'EB Garamond',serif;text-transform:none;letter-spacing:.03em;font-size:clamp(13px,1.5vw,16px);color:#e8f0ff;background:rgba(4,10,30,.55);white-space:nowrap;font-weight:400}
.ds-bt{font-family:'Cinzel',serif;text-transform:uppercase;letter-spacing:.1em;font-size:clamp(10px,1.15vw,12px);padding:5px 10px;font-weight:700}
.ds-key:hover,.ds-bt:hover{border-color:rgba(190,215,255,.8)}
.ds-key.on,.ds-bt.on{border-color:#ffe08a;color:#0b1636;background:linear-gradient(180deg,#ffe08a,#d9a93f);text-shadow:none;box-shadow:0 0 10px rgba(255,210,120,.5)}
.ds-key.cap{animation:dsBlink .8s infinite;color:#0b1636;background:#9fd0ff;border-color:#e8f0ff}
.ds-key.emp{color:#6c7fa3}
.ds-key.on.emp{color:#3a4a6a}
.ds-bt.dis{opacity:.3;cursor:default}
.ds-desc{font-family:'EB Garamond',serif;color:#9fb3d6;text-align:center;min-height:1.5em;padding:2px 12px;font-size:clamp(14px,1.6vw,17px);flex:0 0 auto}
.ds-hints{display:flex;flex-wrap:wrap;justify-content:center;gap:4px 18px;font-size:clamp(10px,1.1vw,12px);letter-spacing:.12em;color:#9fb3d6;text-transform:uppercase;padding:6px 0 2px;flex:0 0 auto;font-weight:700}
.ds-hint{display:inline-flex;align-items:center;gap:7px;cursor:pointer;white-space:nowrap}
.ds-hint:hover{color:#f3d27a}
.ds-hint kbd{display:inline-block;min-width:22px;padding:1px 7px;border:1px solid rgba(190,215,255,.55);border-radius:4px;color:#f3d27a;
 font-family:'EB Garamond',serif;font-size:13px;letter-spacing:.02em;text-transform:none;text-align:center;background:rgba(4,8,22,.6);font-weight:600}
.ds-hint kbd.pad{border-radius:11px}
/* slots */
.ds-slot{min-height:78px;padding:6px 12px 6px 30px;gap:14px;justify-content:flex-start;border:1px solid rgba(190,215,255,.18);margin:5px 0;background:rgba(4,10,30,.35)!important}
.ds-slot.sel{background:linear-gradient(90deg,rgba(80,170,255,.35),rgba(255,210,120,.25))!important;border-color:rgba(190,215,255,.6)}
.ds-thumb{width:58px;height:58px;flex:0 0 58px;display:flex;align-items:center;justify-content:center;border:1px solid rgba(190,215,255,.4);border-radius:6px;
 background:radial-gradient(circle,rgba(70,110,200,.45),rgba(4,8,22,.7))}
.ds-thumb img{width:48px;height:48px;image-rendering:pixelated;image-rendering:crisp-edges}
.ds-sn{font-size:clamp(20px,2.6vw,28px);color:#f3d27a;width:28px;text-align:center;flex:0 0 28px;letter-spacing:0;text-shadow:0 0 10px rgba(243,210,122,.4)}
.ds-si{flex:1 1 auto;min-width:0;display:flex;flex-direction:column;gap:3px}
.ds-si .a{font-size:clamp(12px,1.5vw,15px);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ds-si .b{font-family:'EB Garamond',serif;text-transform:none;letter-spacing:.03em;color:#9fb3d6;font-size:clamp(12px,1.4vw,15px);display:flex;flex-wrap:wrap;gap:2px 16px;font-weight:400;text-shadow:none}
.ds-row.sel .ds-si .b{color:#dce8ff}
.ds-si .e{color:#6c7fa3;font-family:'EB Garamond',serif;font-style:italic;text-transform:none;letter-spacing:.06em;font-size:clamp(14px,1.6vw,17px);font-weight:400}
.ds-del{width:38px;height:38px;flex:0 0 38px;display:flex;align-items:center;justify-content:center;border:1px solid rgba(190,215,255,.3);border-radius:50%;color:#d88a8a;font-size:15px;cursor:pointer;font-family:sans-serif;background:rgba(4,8,22,.5)}
.ds-del:hover,.ds-del.on{border-color:#ff9a8a;color:#fff;background:rgba(170,50,60,.7);box-shadow:0 0 10px rgba(255,100,90,.45)}
/* realms */
.ds-realm .rn{width:48px;flex:0 0 48px;text-align:center;color:#f3d27a;font-size:1.2em;letter-spacing:.04em}
.ds-realm .st{font-family:'EB Garamond',serif;text-transform:none;letter-spacing:.04em;color:#9fb3d6;font-size:.98em;font-weight:400}
.ds-realm .ok{color:#f3d27a}
.ds-realm .here{color:#9fd0ff}
.ds-realm.lock .rn,.ds-realm.lock .ds-lab{color:#6c7fa3}
/* modal */
.ds-modal{background:rgba(4,7,15,.55)}
.ds-modal::before,.ds-modal::after{display:none}
.ds-modal .ds-panel{width:min(500px,100%);padding:20px 26px 10px}
.ds-q{font-family:'EB Garamond',serif;font-size:clamp(17px,2vw,21px);color:#e8f0ff;text-align:center;padding:4px 6px 12px;line-height:1.35}
.ds-modal .ds-row{justify-content:center;min-height:40px;font-size:clamp(14px,1.7vw,17px);letter-spacing:.3em;width:min(260px,100%);margin:3px auto;padding-left:30px}
/* text pages */
.ds-text{font-family:'EB Garamond',serif;color:#e8f0ff;font-size:clamp(14px,1.6vw,17px);line-height:1.45;padding:0 10px 10px}
.ds-text h3{font-family:'Cinzel',serif;font-weight:700;color:#f3d27a;letter-spacing:.22em;text-transform:uppercase;font-size:clamp(12px,1.35vw,14px);
 margin:16px 0 6px;padding:4px 12px;background:linear-gradient(90deg,rgba(243,210,122,.25),transparent);border-left:3px solid #f3d27a;border-radius:0 3px 3px 0}
.ds-text p{margin:4px 0;color:#d6e2f8}
.ds-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(300px,100%),1fr));gap:4px 26px}
.ds-text table{border-collapse:collapse;width:100%}
.ds-text td{padding:3px 6px;border-bottom:1px solid rgba(190,215,255,.14);vertical-align:top}
.ds-text td:first-child{color:#9fb3d6;white-space:nowrap;width:1%;padding-right:14px}
.ds-text kbd{display:inline-block;padding:0 6px;border:1px solid rgba(190,215,255,.5);border-radius:4px;color:#f3d27a;font-family:'EB Garamond',serif;font-size:.92em;margin:1px;background:rgba(4,8,22,.5)}
.ds-ty{display:inline-block;padding:0 8px;margin:1px 2px;border-radius:9px;color:#fff;font-family:'Cinzel',serif;font-size:.76em;letter-spacing:.08em;text-transform:uppercase;font-weight:700;text-shadow:0 1px 1px rgba(0,0,0,.6);border:1px solid rgba(255,255,255,.35)}
/* credits */
.ds-cred .ds-panel{background:transparent;border-color:transparent;box-shadow:none;height:100%}
.ds-crv{flex:1;overflow:hidden;position:relative;-webkit-mask-image:linear-gradient(transparent,#000 14%,#000 86%,transparent);mask-image:linear-gradient(transparent,#000 14%,#000 86%,transparent)}
.ds-crs{position:absolute;left:0;right:0;text-align:center;will-change:transform}
.ds-crs .h{color:#f3d27a;letter-spacing:.28em;text-transform:uppercase;font-size:clamp(12px,1.4vw,14px);margin-top:34px;font-weight:700}
.ds-crs .v{font-family:'EB Garamond',serif;color:#e8f0ff;font-size:clamp(16px,2vw,21px);margin-top:6px}
.ds-crs .v.s{font-family:'Cinzel',serif;letter-spacing:.2em;text-transform:uppercase;color:#cfe0ff}
.ds-crs .v.i{font-style:italic;color:#9fb3d6}
.ds-crs .v.g{font-family:'Cinzel',serif;color:#f3d27a;letter-spacing:.3em;text-transform:uppercase}
.ds-crs .big{font-size:clamp(40px,8vw,84px);letter-spacing:.22em;padding-left:.22em;font-weight:700;
 background:linear-gradient(180deg,#fff7da 0%,#f3d27a 45%,#c48a2c 85%);-webkit-background-clip:text;background-clip:text;color:transparent;animation:dsGlow 4s ease-in-out infinite}
.ds-crs .end{font-family:'EB Garamond',serif;font-style:italic;color:#dce8ff;font-size:clamp(16px,2.1vw,22px);max-width:640px;margin:18px auto 0;line-height:1.5;padding:0 10px}
/* title & splash */
.ds-logo{font-size:clamp(46px,10vw,124px);letter-spacing:.22em;padding-left:.22em;font-weight:700;line-height:1.05;text-align:center;
 background:linear-gradient(180deg,#fff7da 0%,#ffe08a 38%,#d9a93f 72%,#9a6a1e 100%);-webkit-background-clip:text;background-clip:text;color:transparent;
 animation:dsGlow 4s ease-in-out infinite}
.ds-subt{display:flex;align-items:center;gap:14px;justify-content:center;color:#e8f0ff;letter-spacing:.28em;text-transform:uppercase;font-size:clamp(11px,1.7vw,17px);margin-top:12px;text-align:center;font-weight:700;
 text-shadow:0 0 10px rgba(120,170,255,.6)}
.ds-subt::before,.ds-subt::after{content:'◆';color:#f3d27a;font-size:.6em;text-shadow:0 0 8px rgba(255,210,120,.8);flex:0 0 auto}
.ds-subt2{font-family:'EB Garamond',serif;font-style:italic;color:#9fb3d6;text-align:center;font-size:clamp(13px,1.6vw,17px);margin-top:6px;letter-spacing:.06em}
.ds-splash,.ds-titlescr{background:radial-gradient(ellipse at 50% 42%,rgba(4,7,15,0) 0%,rgba(4,7,15,.2) 55%,rgba(4,7,15,.85) 100%)}
.ds-splash{flex-direction:column;cursor:pointer}
.ds-press{margin-top:clamp(30px,9vh,90px);letter-spacing:.36em;padding-left:.36em;text-transform:uppercase;font-size:clamp(11px,1.5vw,15px);color:#f3d27a;animation:dsBlink 2.2s ease-in-out infinite;text-align:center;font-weight:700}
.ds-press small{display:block;margin-top:6px;font-size:.8em;color:#9fb3d6;letter-spacing:.3em}
.ds-titlescr{flex-direction:column;justify-content:space-between}
.ds-tlogo{flex:1 1 auto;display:flex;flex-direction:column;justify-content:center;min-height:0;padding-top:2vh}
.ds-tlogo .ds-logo{font-size:clamp(40px,8vw,100px)}
.ds-tmenu{display:flex;flex-direction:column;align-items:center;flex:0 0 auto;width:min(460px,100%);padding:10px 14px 8px;border-radius:9px;
 background:linear-gradient(180deg,rgba(20,40,90,.72),rgba(8,16,44,.82));border:1px solid rgba(190,215,255,.5);box-shadow:inset 0 0 22px rgba(120,170,255,.16),0 10px 40px rgba(0,0,0,.5)}
.ds-tmenu .ds-body{width:100%;padding:0}
.ds-tmenu .ds-row{justify-content:center;min-height:clamp(30px,4.4vh,38px);font-size:clamp(13px,1.55vw,16px);letter-spacing:.22em;padding:2px 30px}
.ds-tmenu .ds-row:nth-child(even){background:none}
.ds-tmenu .ds-row.sel{background:linear-gradient(90deg,rgba(80,170,255,.05),rgba(80,170,255,.35) 25%,rgba(255,210,120,.25) 75%,rgba(255,210,120,.05))}
.ds-tmenu .ds-row.sel::before{left:auto;right:calc(50% + 8.5em)}
.ds-tmenu .ds-lab{flex:0 1 auto}
.ds-tmenu .ds-desc{margin-top:4px;font-size:clamp(13px,1.5vw,16px)}
.ds-tfoot{display:flex;justify-content:space-between;align-items:flex-end;width:100%;font-family:'EB Garamond',serif;font-size:12px;color:#6c7fa3;letter-spacing:.08em;padding:4px 6px 0}
.ds-langsw{position:absolute;top:max(10px,env(safe-area-inset-top));right:max(14px,env(safe-area-inset-right));display:flex;gap:0;align-items:center;font-size:12px;letter-spacing:.16em;z-index:2;
 border:1px solid rgba(190,215,255,.45);border-radius:999px;overflow:hidden;background:rgba(8,16,44,.7);font-weight:700}
.ds-langsw span{padding:6px 12px;cursor:pointer;color:#9fb3d6}
.ds-langsw span.on{color:#0b1636;background:linear-gradient(180deg,#ffe08a,#d9a93f)}
.ds-langsw i{display:none}
.ds-toast{position:absolute;left:50%;top:max(16px,env(safe-area-inset-top));transform:translateX(-50%);z-index:30;pointer-events:none;border-radius:8px;
 background:linear-gradient(180deg,rgba(20,40,90,.96),rgba(8,16,44,.97));border:1px solid rgba(190,215,255,.6);padding:10px 22px;color:#f3d27a;font-family:'Cinzel',serif;letter-spacing:.12em;font-weight:700;
 font-size:clamp(12px,1.4vw,14px);text-align:center;max-width:90vw;box-shadow:inset 0 0 18px rgba(120,170,255,.2),0 8px 30px rgba(0,0,0,.6);animation:dsFade .2s}
@media (orientation:portrait){.ds-splash,.ds-titlescr{background:radial-gradient(ellipse at 50% 22%,rgba(27,47,107,.25) 0%,rgba(10,18,48,.75) 50%,rgba(4,7,15,.95) 100%)}}
@media (max-height:520px){
 .ds-ov{padding:max(6px,env(safe-area-inset-top)) max(10px,env(safe-area-inset-right)) max(6px,env(safe-area-inset-bottom)) max(10px,env(safe-area-inset-left))}
 .ds-panel{padding:8px 14px 6px}.ds-line{margin:4px 0}.ds-head{min-height:24px}.ds-title{font-size:15px}.ds-x{width:28px;height:28px}
 .ds-row{min-height:31px;font-size:12px}.ds-desc{font-size:13px;min-height:1.3em}.ds-hints{padding-top:3px;font-size:10px}
 .ds-tab{padding:3px 11px;font-size:11px}.ds-slot{min-height:58px;margin:3px 0}.ds-thumb{width:46px;height:46px;flex-basis:46px}.ds-thumb img{width:40px;height:40px}
 .ds-titlescr{flex-direction:row;flex-wrap:wrap;align-items:center;justify-content:center;gap:0 2vw}
 .ds-tlogo{flex:1 1 40%;padding-top:0}.ds-tlogo .ds-logo{font-size:clamp(34px,7vw,64px)}.ds-tlogo .ds-subt{font-size:11px;gap:8px}.ds-tlogo .ds-subt2{font-size:12px}
 .ds-tmenu{flex:0 1 44%;padding:6px 8px}.ds-tmenu .ds-row{min-height:28px;font-size:12px}.ds-tmenu .ds-desc{display:none}
 .ds-tfoot{flex:1 1 100%;padding:0 6px}
 .ds-langsw{right:auto;left:max(14px,env(safe-area-inset-left))}
}
@media (max-width:620px){
 .ds-panel{padding:12px 10px 8px}.ds-row{padding:2px 6px 2px 22px;gap:8px;letter-spacing:.06em}.ds-row.sel::before{left:6px;font-size:9px}.ds-x{right:-2px}
 .ds-vtx{min-width:78px}.ds-arr{width:22px}.ds-sl{width:84px}.ds-num{min-width:36px}
 .ds-key{min-width:58px;padding:3px 4px}.ds-bt{min-width:0;padding:5px 7px;letter-spacing:.05em}
 .ds-title{letter-spacing:.18em}.ds-tab{padding:5px 11px;letter-spacing:.1em}.ds-tabkey{display:none}
 .ds-tabs{flex-wrap:wrap;gap:5px}
 .ds-row.wrap{flex-wrap:wrap;padding-top:4px;padding-bottom:5px;row-gap:4px}.ds-row.wrap .ds-lab{flex:1 1 100%;white-space:normal}.ds-row.wrap .ds-val{margin-left:auto;flex-wrap:wrap;justify-content:flex-end}
 .ds-slot{gap:9px;padding:6px 8px 6px 22px}.ds-sn{width:18px;flex-basis:18px}
 .ds-hints{gap:4px 12px}
}
`);

// ---------- helpers ----------
function _mEsc(s){return String(s==null?'':s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));}
function _mSfx(n){if(typeof sfx==='function'){try{sfx(n);}catch(e){}}}
function _mDev(){const h=SET.controlHints;if(h&&h!=='auto')return h;return typeof lastDevice!=='undefined'&&lastDevice?lastDevice:'keyboard';}
function _mKey(a){const k=SET.keys&&SET.keys[a];const c=k?(k[0]||k[1]):'';if(!c)return'—';return typeof keyName==='function'?keyName(c):c.replace(/^Key|^Digit/,'');}
function _mPad(a){const k=SET.pad&&SET.pad[a];const b=k?(k[0]>=0?k[0]:k[1]):-1;if(b==null||b<0)return'—';return typeof padBtnName==='function'?padBtnName(b):'B'+b;}
function _mFmtTime(s){s=Math.floor(s||0);const h=Math.floor(s/3600),m=Math.floor(s/60)%60,ss=s%60;return h+':'+String(m).padStart(2,'0')+':'+String(ss).padStart(2,'0');}
function _mFmtDate(ms){try{return new Date(ms).toLocaleString(LANG==='pl'?'pl-PL':'en-GB',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'});}catch(e){return'';}}
const _M_ROMAN=['I','II','III','IV','V','VI','VII','VIII','IX','X'];
function _mRealm(li){const L=typeof LEVELS!=='undefined'&&LEVELS[li];return{roman:(L&&L.roman)||_M_ROMAN[li]||'?',name:L?L2(L.name):'—'};}
const _mThumbs={};
function _mThumb(sp){if(!sp||typeof monSprite!=='function'||(typeof SPECIES!=='undefined'&&!Object.prototype.hasOwnProperty.call(SPECIES,sp)))return'';if(_mThumbs[sp])return _mThumbs[sp];
  try{const c=monSprite(sp);if(!c)return'';const o=document.createElement('canvas');o.width=c.width*2;o.height=c.height*2;const x=o.getContext('2d');x.imageSmoothingEnabled=false;
    x.drawImage(c,0,0,o.width,o.height);return _mThumbs[sp]=o.toDataURL();}catch(e){return'';}}
function dsToast(msg,ms){const r=document.getElementById('ovroot');if(!r)return;const d=document.createElement('div');d.className='ds-toast';d.textContent=msg;r.appendChild(d);
  setTimeout(()=>{d.style.transition='opacity .4s';d.style.opacity='0';setTimeout(()=>d.remove(),450);},ms||2400);}
// push a screen; full screens hide the overlays beneath them (restored on close), modals keep them visible
function _mPush(o){const modal=/ds-modal/.test(o.el.className);const hidden=[];
  if(!modal)for(const u of ovStack)if(u.el&&u.el.style.visibility!=='hidden'){u.el.style.visibility='hidden';hidden.push(u);}
  const oc=o.onClose;o.onClose=()=>{for(const u of hidden)if(u.el)u.el.style.visibility='';oc&&oc();};pushOverlay(o);}
function closeAllOverlays(){let g=50;while(ovStack.length&&g--)popOverlay(ovStack[ovStack.length-1]);}
function _mRefreshAll(){for(const o of ovStack)if(o.refresh)o.refresh();}
function _mApply(){saveSettings();applySettings();if(typeof applyAudio==='function'){try{applyAudio();}catch(e){}}}

// hint bar markup. items: [{a:'ok'|['left','right'], l:'label', act?:fn}]
function _mHints(items){const dev=_mDev();return items.map((h,i)=>{const as=Array.isArray(h.a)?h.a:[h.a];let k;
  if(dev==='touch'||dev==='mouse'){const w=dev==='touch'?t('m_tap'):t('m_click');
    k=as[0]==='ok'?w:as[0]==='back'?'✕':as[0]==='left'?'‹ ›':as[0]==='rotL'?'⇆':as[0]==='up'?'⇅':as[0]==='menu'?'🗑':w;
    return`<span class="ds-hint" data-h="${i}"><kbd>${_mEsc(k)}</kbd>${_mEsc(h.l)}</span>`;}
  const pad=dev==='pad';k=as.map(a=>pad?_mPad(a):_mKey(a)).filter((v,j,arr)=>arr.indexOf(v)===j).join(pad?' ':' / ');
  return`<span class="ds-hint" data-h="${i}"><kbd class="${pad?'pad':''}">${_mEsc(k)}</kbd>${_mEsc(h.l)}</span>`;}).join('');}

// ---------- generic list screen ----------
// cfg: {cls, title(), tabs?(), rows(), hints(), html?(), back:value, noBack, onBack?, onMenu?(row), head?(), wrap?(el,panel) , lr? (left/right move like up/down), close button}
function dsScreen(cfg){
  const el=document.createElement('div');el.className='ds-ov '+(cfg.cls||'');
  const o={el,cfg,sel:-1,sub:0,tab:cfg.tab||0,rows:[],capturing:null,done:false,result:cfg.back,_dev:null};
  let res;o.promise=new Promise(r=>res=r);
  o.onClose=()=>{o.done=true;if(o._iv)clearInterval(o._iv);if(o._raf)cancelAnimationFrame(o._raf);if(cfg.onClosed)cfg.onClosed();res(o.result);};
  o.close=v=>{if(o.done)return;o.result=v;popOverlay(o);};
  const selectable=r=>r&&r.type!=='hdr'&&r.type!=='text'&&!r.dis;
  function firstSel(){for(let i=0;i<o.rows.length;i++)if(selectable(o.rows[i]))return i;return -1;}
  o.render=function(){
    const body0=el.querySelector('.ds-body');const st=body0?body0.scrollTop:0;
    o.rows=cfg.rows?cfg.rows(o):[];
    if(o.sel<0||!selectable(o.rows[o.sel])){if(o.sel>=0){let j=o.sel;while(j<o.rows.length&&!selectable(o.rows[j]))j++;if(j>=o.rows.length){j=o.sel;while(j>=0&&!selectable(o.rows[j]))j--;}o.sel=j;}if(o.sel<0)o.sel=firstSel();}
    let h='';
    if(cfg.pre)h+=cfg.pre(o);
    h+=`<div class="ds-panel">`;
    if(cfg.title)h+=`<div class="ds-head"><div class="ds-title">${_mEsc(cfg.title(o))}</div>${cfg.noX?'':'<div class="ds-x" data-x="1">✕</div>'}</div><div class="ds-line"></div>`;
    if(cfg.q)h+=`<div class="ds-q">${_mEsc(cfg.q)}</div>`;
    if(cfg.tabs){const tb=cfg.tabs(o);const dv=_mDev();const kl=dv==='pad'?_mPad('rotL'):dv==='keyboard'?_mKey('rotL'):'',kr=dv==='pad'?_mPad('rotR'):dv==='keyboard'?_mKey('rotR'):'';
      h+=`<div class="ds-tabs">${kl?`<span class="ds-tabkey">${_mEsc(kl)}</span>`:''}${tb.map((s,i)=>`<div class="ds-tab${i===o.tab?' on':''}" data-tab="${i}">${_mEsc(s)}</div>`).join('')}${kr?`<span class="ds-tabkey">${_mEsc(kr)}</span>`:''}</div><div class="ds-line"></div>`;}
    h+=`<div class="ds-body">${cfg.html?cfg.html(o):''}${o.rows.map((r,i)=>_mRowHTML(o,r,i)).join('')}</div>`;
    if(!cfg.noDesc)h+=`<div class="ds-line"></div><div class="ds-desc"></div>`;
    h+=`<div class="ds-hints"></div></div>`;
    if(cfg.post)h+=cfg.post(o);
    el.innerHTML=h;
    if(cfg.wrap)cfg.wrap(o);
    const body=el.querySelector('.ds-body');body.scrollTop=st;
    o.bind();o.updSel(false);o.updHints();
  };
  o.updHints=function(){o._dev=_mDev();const hb=el.querySelector('.ds-hints');if(!hb)return;const hs=cfg.hints?cfg.hints(o):[];o._hs=hs;hb.innerHTML=_mHints(hs);
    hb.querySelectorAll('.ds-hint').forEach(n=>n.addEventListener('click',e=>{e.stopPropagation();const hh=hs[+n.dataset.h];if(!hh)return;
      if(hh.act)hh.act();else o.input(Array.isArray(hh.a)?hh.a[hh.a.length-1]:hh.a,false);}));};
  o.updSel=function(scroll){{const r0=o.rows[o.sel];if(r0&&r0.subs&&(o.sub>=r0.subs()||(r0.subDis&&r0.subDis(o.sub))))o.sub=_mDefSub(r0);}
    el.querySelectorAll('.ds-row').forEach(n=>{const i=+n.dataset.i;n.classList.toggle('sel',i===o.sel);
      n.querySelectorAll('[data-sub]').forEach(b=>b.classList.toggle('on',i===o.sel&&+b.dataset.sub===o.sub));});
    const d=el.querySelector('.ds-desc');const r=o.rows[o.sel];
    if(d){let s=r&&r.desc!=null?(typeof r.desc==='function'?r.desc():r.desc):(cfg.desc?cfg.desc(o):'');d.textContent=s||' ';}
    if(scroll!==false){const n=el.querySelector(`.ds-row[data-i="${o.sel}"]`);if(n&&n.scrollIntoView)n.scrollIntoView({block:'nearest'});}};
  o.setSel=function(i,sub){if(i===o.sel&&(sub==null||sub===o.sub))return;if(i!==o.sel)o.sub=sub!=null?sub:_mDefSub(o.rows[i]);else o.sub=sub;o.sel=i;o.updSel(false);};
  o.bind=function(){
    const x=el.querySelector('[data-x]');if(x)x.addEventListener('click',e=>{e.stopPropagation();o.input('back',false);});
    el.querySelectorAll('.ds-tab').forEach(n=>n.addEventListener('click',e=>{e.stopPropagation();const i=+n.dataset.tab;if(i!==o.tab){o.tab=i;o.sel=-1;o.sub=0;_mSfx('move');el.querySelector('.ds-body').scrollTop=0;o.render();}}));
    el.querySelectorAll('.ds-row').forEach(n=>{const i=+n.dataset.i,r=o.rows[i];
      n.addEventListener('pointermove',e=>{if(e.pointerType==='mouse'&&!o.capturing&&selectable(r)&&o.sel!==i){o.setSel(i);}});
      n.addEventListener('click',e=>{if(o.capturing||!r)return;if(!selectable(r)){_mSfx('deny');return;}
        const sb=e.target.closest('[data-sub]'),ar=e.target.closest('[data-arr]');
        if(e.target.closest('.ds-sl'))return;
        if(ar){o.setSel(i);o.change(+ar.dataset.arr);return;}
        if(sb){o.setSel(i,+sb.dataset.sub);o.activate();return;}
        if(o.sel!==i)o.setSel(i);
        o.activate();});
      const sl=n.querySelector('.ds-sl');if(sl&&r.type==='slider'){
        const setFromX=cx=>{const rc=sl.getBoundingClientRect();let k=clamp((cx-rc.left)/rc.width,0,1);let v=r.min+k*(r.max-r.min);v=Math.round(v/r.step)*r.step;v=clamp(v,r.min,r.max);
          if(v!==r.get()){r.set(v);_mSliderUpd(n,r);}};
        sl.addEventListener('pointerdown',e=>{e.preventDefault();e.stopPropagation();o.setSel(i);try{sl.setPointerCapture(e.pointerId);}catch(_){}sl._drag=true;setFromX(e.clientX);});
        sl.addEventListener('pointermove',e=>{if(sl._drag)setFromX(e.clientX);});
        const end=e=>{if(sl._drag){sl._drag=false;_mSfx('move');if(r.after)r.after();}};
        sl.addEventListener('pointerup',end);sl.addEventListener('pointercancel',end);}
    });
    el.addEventListener('contextmenu',e=>{e.preventDefault();});
  };
  o.move=function(d){const n=o.rows.length;if(!n)return;let i=o.sel;for(let k=0;k<n;k++){i+=d;if(i<0)i=cfg.noWrap?0:n-1;if(i>=n)i=cfg.noWrap?n-1:0;if(selectable(o.rows[i]))break;}
    if(i!==o.sel&&selectable(o.rows[i])){o.sel=i;o.sub=_mDefSub(o.rows[i]);_mSfx('move');o.updSel();}};
  o.change=function(d){const r=o.rows[o.sel];if(!r)return;
    if(r.type==='opt'){const vs=r.vals();const cur=vs.indexOf(r.get());let j=cur+d;if(r.noWrap)j=clamp(j,0,vs.length-1);else j=(j+vs.length)%vs.length;if(j===cur){_mSfx('deny');return;}
      r.set(vs[j]);_mSfx('move');o.render();if(r.after)r.after();}
    else if(r.type==='slider'){const v=clamp(r.get()+d*r.step,r.min,r.max);if(v===r.get())return;r.set(v);_mSfx('move');const n=el.querySelector(`.ds-row[data-i="${o.sel}"]`);if(n)_mSliderUpd(n,r);if(r.after)r.after();}
    else if(r.subs){const ns=r.subs();let j=o.sub;for(let k=0;k<ns;k++){j=clamp(j+d,0,ns-1);if(!r.subDis||!r.subDis(j))break;}if(j!==o.sub&&(!r.subDis||!r.subDis(j))){o.sub=j;_mSfx('move');o.updSel(false);}}
    else if(cfg.lr)o.move(d);};
  o.activate=function(){const r=o.rows[o.sel];if(!r)return;if(r.dis){_mSfx('deny');return;}
    if(r.type==='opt')o.change(1);
    else if(r.type==='slider'){}
    else if(r.subs){if(r.subDis&&r.subDis(o.sub)){_mSfx('deny');return;}r.act(o.sub,o);}
    else if(r.act){r.act(o);}};
  o.input=function(a,rep){if(o.capturing||o.done)return;
    if(cfg.onInput&&cfg.onInput(a,rep))return;
    switch(a){
      case'up':o.move(-1);break;case'down':o.move(1);break;
      case'left':o.change(-1);break;case'right':o.change(1);break;
      case'rotL':case'zoomOut':if(cfg.tabs&&!rep){const n=cfg.tabs(o).length;o.tab=(o.tab+n-1)%n;o.sel=-1;_mSfx('move');o.render();el.querySelector('.ds-body').scrollTop=0;}break;
      case'rotR':case'zoomIn':if(cfg.tabs&&!rep){const n=cfg.tabs(o).length;o.tab=(o.tab+1)%n;o.sel=-1;_mSfx('move');o.render();el.querySelector('.ds-body').scrollTop=0;}break;
      case'ok':if(!rep)o.activate();break;
      case'menu':if(rep)break;if(cfg.onMenu){cfg.onMenu(o);break;}if(cfg.menuCloses){_mSfx('back');o.close(cfg.back);}break;
      case'back':if(rep)break;if(cfg.noBack){_mSfx('deny');break;}if(cfg.onBack){cfg.onBack(o);break;}_mSfx('back');o.close(cfg.back);break;
    }};
  o.refresh=()=>{if(!o.done)o.render();};
  o._iv=setInterval(()=>{if(o.done)return;if(_mDev()!==o._dev){if(cfg.tabs)o.render();else o.updHints();}if(cfg.tick)cfg.tick(o);},300);
  return o;
}
function _mDefSub(r){if(!r||!r.subs)return 0;const n=r.subs();for(let j=0;j<n;j++)if(!r.subDis||!r.subDis(j))return j;return 0;}
function _mSliderUpd(n,r){const k=(r.get()-r.min)/(r.max-r.min);const b=n.querySelector('.ds-sl b'),s=n.querySelector('.ds-sl s'),u=n.querySelector('.ds-num');
  if(b)b.style.width=(k*100)+'%';if(s)s.style.left=(k*100)+'%';if(u)u.textContent=r.fmt?r.fmt(r.get()):r.get();}
function _mRowHTML(o,r,i){
  if(r.type==='hdr')return`<div class="ds-hdr" data-i="${i}">${_mEsc(r.label)}</div>`;
  if(r.type==='text')return`<div class="ds-text" data-i="${i}">${r.html}</div>`;
  const cls='ds-row'+(r.dis?' dis':'')+(r.cls?' '+r.cls:'');
  if(r.html)return`<div class="${cls}" data-i="${i}">${r.html()}</div>`;
  let v='';
  if(r.type==='opt'){const vs=r.vals();const cur=r.get();v=`<span class="ds-val"><span class="ds-arr" data-arr="-1">‹</span><span class="ds-vtx">${_mEsc(r.name(cur))}</span><span class="ds-arr" data-arr="1">›</span></span>`;}
  else if(r.type==='slider'){const k=(r.get()-r.min)/(r.max-r.min)*100;
    v=`<span class="ds-val"><span class="ds-arr" data-arr="-1">‹</span><span class="ds-sl"><i></i><b style="width:${k}%"></b><s style="left:${k}%"></s></span><span class="ds-arr" data-arr="1">›</span><span class="ds-num">${_mEsc(r.fmt?r.fmt(r.get()):r.get())}</span></span>`;}
  else if(r.type==='info')v=`<span class="ds-val">${_mEsc(r.value())}</span>`;
  else if(r.subs)v=`<span class="ds-val">${r.subHTML()}</span>`;
  else if(r.value)v=`<span class="ds-val">${_mEsc(r.value())}</span>`;
  return`<div class="${cls}" data-i="${i}"><span class="ds-lab">${_mEsc(r.label)}</span>${v}</div>`;
}
// row builders
const _mOO=v=>v?t('m_on'):t('m_off');
function _rBool(key,after){return{type:'opt',label:t('m_'+key),desc:t('m_d_'+key),vals:()=>[true,false],get:()=>!!SET[key],set:v=>{SET[key]=v;_mApply();},name:_mOO,after};}
function _rOpt(key,vals,names,after){return{type:'opt',label:t('m_'+key),desc:t('m_d_'+key),vals:()=>vals,get:()=>SET[key],set:v=>{SET[key]=v;_mApply();},name:v=>names[vals.indexOf(v)]||String(v),noWrap:false,after};}
function _rSlider(key,min,max,step,fmt,after){return{type:'slider',label:t('m_'+key),desc:t('m_d_'+key),min,max,step,get:()=>+SET[key],set:v=>{SET[key]=v;_mApply();},fmt,after};}
function _rBtn(label,desc,act,o){return Object.assign({type:'btn',label,desc,act},o||{});}

// ---------- confirm ----------
function confirmDS(text){
  const o=dsScreen({cls:'ds-modal',q:text,back:false,lr:true,noDesc:true,
    rows:()=>[_rBtn(t('m_yes'),null,()=>{_mSfx('ok');o.close(true);}),_rBtn(t('m_no'),null,()=>{_mSfx('back');o.close(false);})],
    hints:()=>[{a:'ok',l:t('m_select')},{a:'back',l:t('m_no')}]});
  o.render();o.sel=1;o.updSel(false);_mPush(o);return o.promise;}

// ---------- fullscreen ----------
function toggleFullscreen(){
  const d=document,de=d.documentElement;const fs=d.fullscreenElement||d.webkitFullscreenElement;
  try{
    if(fs){(d.exitFullscreen||d.webkitExitFullscreen).call(d);return;}
    const req=de.requestFullscreen||de.webkitRequestFullscreen||de.msRequestFullscreen;
    if(!req){dsToast(/iPhone|iPod|iPad/.test(navigator.userAgent)?t('m_fs_ios'):t('m_fs_no'),4200);return;}
    const p=req.call(de);
    const lock=()=>{const ph=Math.min(screen.width,screen.height)<=820&&('ontouchstart' in window);
      if(ph&&screen.orientation&&screen.orientation.lock)screen.orientation.lock('landscape').catch(()=>{});};
    if(p&&p.then)p.then(lock).catch(()=>dsToast(/iPhone|iPod|iPad/.test(navigator.userAgent)?t('m_fs_ios'):t('m_fs_no'),4200));else lock();
  }catch(e){dsToast(t('m_fs_no'));}
}
function _mIsFs(){return!!(document.fullscreenElement||document.webkitFullscreenElement);}
['fullscreenchange','webkitfullscreenchange'].forEach(ev=>document.addEventListener(ev,()=>{setTimeout(()=>{_mRefreshAll();if(typeof resize==='function'&&cvs)resize();},60);}));

// ---------- splash ----------
let _splashOv=null,_splashDone=false;
function showSplash(){scene='splash';_splashDone=false;
  const el=document.createElement('div');el.className='ds-ov ds-splash';
  el.innerHTML=`<div class="ds-logo">LUMINA</div><div class="ds-subt">${_mEsc(t('m_sub'))}</div><div class="ds-subt2">${_mEsc(t('m_sub2'))}</div>
   <div class="ds-press">${_mEsc(t('m_press'))}${LANG==='pl'?'<small>Press any button</small>':''}</div>`;
  const go=e=>{e.preventDefault();splashAny();};el.addEventListener('pointerdown',go);
  _splashOv={el,input(){splashAny();}};pushOverlay(_splashOv);}
function splashAny(){if(_splashDone)return;_splashDone=true;
  if(typeof audioInit==='function'){try{audioInit();}catch(e){}}
  _mSfx('ok');if(_splashOv)popOverlay(_splashOv);_splashOv=null;showTitle();}

// ---------- title ----------
let _titleOv=null;
function _mStartGame(fn){closeAllOverlays();_titleOv=null;try{fn();}catch(e){console.error(e);}}
function showTitle(){
  scene='title';ui.length=0;closeAllOverlays();
  if(typeof playMusic==='function'){try{playMusic('menu');}catch(e){}}
  const o=dsScreen({cls:'ds-titlescr',noBack:true,noDesc:true,noWrap:false,
    pre:()=>`<div class="ds-langsw"><span data-lang="pl" class="${LANG==='pl'?'on':''}">PL</span><i>|</i><span data-lang="en" class="${LANG==='en'?'on':''}">EN</span></div>
      <div class="ds-tlogo"><div class="ds-logo">LUMINA</div><div class="ds-subt">${_mEsc(t('m_sub'))}</div><div class="ds-subt2">${_mEsc(t('m_sub2'))}</div></div>`,
    post:()=>`<div class="ds-tfoot"><span>v1.0</span><span>${LANG==='pl'?'Wygenerowane z pomocą Claude':'Generated with Claude'}</span></div>`,
    wrap:(o)=>{const p=o.el.querySelector('.ds-panel');p.className='ds-tmenu';const d=document.createElement('div');d.className='ds-desc';p.insertBefore(d,p.querySelector('.ds-hints'));
      o.el.querySelectorAll('[data-lang]').forEach(n=>n.addEventListener('click',e=>{e.stopPropagation();SET.lang=n.dataset.lang;_mApply();_mSfx('move');o.render();}));},
    rows:()=>{const ls=latestSlot(),m=ls?slotMeta(ls):null,R=[];
      if(m){const rr=_mRealm(m.li);R.push(_rBtn(t('m_continue'),t('m_d_continue',`${rr.roman} · ${rr.name} · ${_mFmtTime(m.time)}`),()=>{_mSfx('ok');
        if(loadFromSlot(ls))_mStartGame(()=>{if(typeof resumeGame==='function')resumeGame();});}));}
      R.push(_rBtn(t('m_new'),t('m_d_new'),async()=>{_mSfx('ok');await openSaveLoad('new');}));
      R.push(_rBtn(t('m_load'),t('m_d_load'),async()=>{_mSfx('ok');await openSaveLoad('load');},{dis:!ls}));
      if(ls)R.push(_rBtn(t('m_realm'),t('m_d_realm'),async()=>{_mSfx('ok');const s=latestSlot();if(!loadFromSlot(s))return;const li=await openLevelSelect();
        if(li>=0)_mStartGame(()=>{if(typeof enterLevel==='function')enterLevel(li,{heal:true});});else{game=null;o.refresh();}}));
      R.push(_rBtn(t('m_settings'),t('m_d_settings'),async()=>{_mSfx('ok');await openSettings();o.refresh();}));
      R.push(_rBtn(t('m_help'),t('m_d_help'),async()=>{_mSfx('ok');await showHelp();}));
      R.push(_rBtn(t('m_credits'),t('m_d_credits'),async()=>{_mSfx('ok');await showCredits({});}));
      R.push(_rBtn(t('m_fullscreen'),t('m_d_fullscreen'),()=>{_mSfx('ok');toggleFullscreen();}));
      return R;},
    hints:()=>[{a:'ok',l:t('m_select')}]});
  o.render();_titleOv=o;_mPush(o);return o;}

// title canvas
const _ttl={emb:[],stars:[],sil:null,init:false};
function _ttlInit(){_ttl.init=true;const r=RNG(77);
  for(let i=0;i<70;i++)_ttl.stars.push({x:r()*W,y:r()*H*0.75,s:r()<.15?2:1,p:r()*6.28,f:.5+r()*1.5});
  for(let i=0;i<46;i++)_ttl.emb.push(_ttlEmb(r,true));}
function _ttlEmb(r,any){r=r||Math.random;return{x:r()*W,y:any?r()*H:H+4,vy:6+r()*16,vx:-3+r()*6,a:.3+r()*.7,s:r()<.2?2:1,p:r()*6.28,hot:r()<.4};}
function titleRender(){
  if(!_ttl.init)_ttlInit();const T=now();
  ctx.save();
  // night‑blue to ember gradient
  let g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#04070f');g.addColorStop(.6,'#0a1230');g.addColorStop(1,'#13234f');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
  for(const s of _ttl.stars){const a=.25+.35*Math.sin(T*s.f+s.p);ctx.fillStyle=`rgba(220,230,255,${Math.max(0,a)})`;ctx.fillRect(s.x|0,s.y|0,s.s,s.s);}
  // eclipse disc / halo
  const cx=W/2,cy=H*0.42,pul=.5+.5*Math.sin(T*.7);
  g=ctx.createRadialGradient(cx,cy,10,cx,cy,170);g.addColorStop(0,`rgba(255,190,90,${.22+.08*pul})`);g.addColorStop(.35,'rgba(60,110,220,.2)');g.addColorStop(.7,'rgba(27,47,107,.18)');g.addColorStop(1,'rgba(0,0,0,0)');
  ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
  // giant silhouette
  if(_ttl.sil===null){_ttl.sil=false;try{if(typeof monSprite==='function'){const c=monSprite('eclipsor');if(c){const o=document.createElement('canvas');o.width=c.width;o.height=c.height;const x=o.getContext('2d');
      x.drawImage(c,0,0);x.globalCompositeOperation='source-in';x.fillStyle='#000';x.fillRect(0,0,o.width,o.height);_ttl.sil=o;}}}catch(e){_ttl.sil=false;}}
  if(_ttl.sil){const sc=Math.floor(200/_ttl.sil.height)||6;const sw=_ttl.sil.width*sc,sh=_ttl.sil.height*sc;ctx.globalAlpha=.42+.08*pul;
    ctx.drawImage(_ttl.sil,Math.round(cx-sw/2),Math.round(cy-sh/2+6+Math.sin(T*.4)*3),sw,sh);ctx.globalAlpha=1;}
  // ring
  ctx.strokeStyle=`rgba(240,190,110,${.25+.15*pul})`;ctx.lineWidth=1;ctx.beginPath();ctx.arc(cx,cy,58+pul*2,0,Math.PI*2);ctx.stroke();
  ctx.strokeStyle='rgba(150,190,255,.3)';ctx.beginPath();ctx.arc(cx,cy,70,0,Math.PI*2);ctx.stroke();
  // crystal
  const cyy=cy+Math.sin(T*1.1)*3;ctx.globalCompositeOperation='lighter';
  g=ctx.createRadialGradient(cx,cyy,0,cx,cyy,40);g.addColorStop(0,`rgba(255,220,140,${.35+.25*pul})`);g.addColorStop(1,'rgba(255,160,60,0)');ctx.fillStyle=g;ctx.fillRect(cx-40,cyy-40,80,80);
  ctx.globalCompositeOperation='source-over';
  ctx.beginPath();ctx.moveTo(cx,cyy-20);ctx.lineTo(cx+9,cyy-2);ctx.lineTo(cx,cyy+20);ctx.lineTo(cx-9,cyy-2);ctx.closePath();
  g=ctx.createLinearGradient(cx-9,cyy-20,cx+9,cyy+20);g.addColorStop(0,'#fff6d8');g.addColorStop(.5,'#f3c060');g.addColorStop(1,'#9a5a1c');ctx.fillStyle=g;ctx.fill();
  ctx.fillStyle='rgba(255,255,255,.55)';ctx.beginPath();ctx.moveTo(cx,cyy-20);ctx.lineTo(cx-9,cyy-2);ctx.lineTo(cx,cyy+2);ctx.closePath();ctx.fill();
  // ground mist
  g=ctx.createLinearGradient(0,H*.7,0,H);g.addColorStop(0,'rgba(0,0,0,0)');g.addColorStop(1,'rgba(40,70,150,.35)');ctx.fillStyle=g;ctx.fillRect(0,H*.7,W,H*.3);
  // embers
  const dt=Math.min(DT||0.016,.05);ctx.globalCompositeOperation='lighter';
  for(let i=0;i<_ttl.emb.length;i++){const e=_ttl.emb[i];e.y-=e.vy*dt;e.x+=(e.vx+Math.sin(T*1.3+e.p)*6)*dt;
    if(e.y<-4||e.x<-6||e.x>W+6){_ttl.emb[i]=_ttlEmb(null,false);continue;}
    const fl=e.a*(.6+.4*Math.sin(T*5+e.p))*clamp(e.y/H*1.6,0,1);
    ctx.fillStyle=e.hot?`rgba(255,${200+((e.p*30)|0)%50},120,${fl})`:`rgba(170,210,255,${fl*.9})`;ctx.fillRect(e.x|0,e.y|0,e.s,e.s);}
  ctx.globalCompositeOperation='source-over';
  // vignette
  g=ctx.createRadialGradient(cx,H/2,H*.35,cx,H/2,W*.62);g.addColorStop(0,'rgba(0,0,0,0)');g.addColorStop(1,'rgba(0,0,0,.75)');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
  ctx.restore();
}

// ---------- settings ----------
function _mBindRow(dev,a){const isK=dev==='key';
  return{type:'bind',label:t('m_act_'+a),desc:isK?t('m_d_bind'):t('m_d_bindp'),subs:()=>2,
    subHTML:function(){return[0,1].map(s=>{const cap=this._o&&this._o.capturing&&this._o.capturing.a===a&&this._o.capturing.dev===dev&&this._o.capturing.s===s;
      const v=isK?(SET.keys[a]||['',''])[s]:(SET.pad[a]||[-1,-1])[s];const e=isK?!v:!(v>=0);
      const nm=cap?t('m_press_key'):e?'—':isK?(typeof keyName==='function'?keyName(v):v):(typeof padBtnName==='function'?padBtnName(v):'B'+v);
      return`<span class="ds-key${cap?' cap':''}${e&&!cap?' emp':''}" data-sub="${s}">${_mEsc(nm)}</span>`;}).join('');},
    act:(s,o)=>{if(typeof startCapture!=='function'){_mSfx('deny');return;}_mSfx('ok');o.capturing={a,dev,s};o.render();
      let fin=false;const done=()=>{if(fin)return;fin=true;o.capturing=null;saveSettings();applySettings();setTimeout(()=>{if(!o.done)o.render();},30);};
      try{startCapture(dev,a,s,done);}catch(e){done();}
      setTimeout(()=>{if(!fin&&o.capturing&&o.capturing.a===a){done();}},isK?10000:10000);}};}
function _mSlotLabel(s){const m=slotMeta(s);if(!m)return t('m_slot',s)+' · '+t('m_empty').replace(/—/g,'').trim();const r=_mRealm(m.li);return`${t('m_slot',s)} · ${r.roman} · ${_mFmtTime(m.time)}`;}
// validate an imported save file before handing it to core (size, structure, sane meta)
function _mValidSave(f){return new Promise(res=>{if(!f||f.size>2e6)return res(false);const fr=new FileReader();fr.onerror=()=>res(false);fr.onload=()=>{try{
  const d=JSON.parse(fr.result),m=d&&d.meta,g=d&&d.data;const isObj=x=>x&&typeof x==='object'&&!Array.isArray(x);
  if(!isObj(m)||!isObj(g)||!Array.isArray(g.party)||!Array.isArray(g.box||[])||!isObj(g.items||{}))return res(false);
  const n=(x,a,b)=>typeof x==='number'&&isFinite(x)&&x>=a&&x<=b;
  if(!n(m.li,0,9)||!n(m.lv||0,0,999)||!n(m.cleared||0,0,10)||!n(m.time||0,0,1e9)||!n(m.date||0,0,1e14))return res(false);
  if(m.lead!=null&&(typeof m.lead!=='string'||m.lead.length>32))return res(false);if(m.name!=null&&(typeof m.name!=='string'||m.name.length>40))return res(false);
  if(g.party.length>6||!g.party.every(x=>isObj(x)&&typeof x.sp==='string'))return res(false);res(true);}catch(e){res(false);}};fr.readAsText(f);});}
function _mImport(s,o){const inp=document.createElement('input');inp.type='file';inp.accept='.json,application/json';inp.style.display='none';document.body.appendChild(inp);
  inp.addEventListener('change',async()=>{const f=inp.files&&inp.files[0];inp.remove();if(!f)return;
    const ok=(await _mValidSave(f))&&(await importToSlot(s,f));dsToast(ok?t('m_imported'):t('m_importFail'));_mSfx(ok?'save':'deny');if(o)o.refresh();_mRefreshAll();});
  inp.click();}
async function _mDelete(s,o){if(!slotMeta(s)){_mSfx('deny');return;}if(await confirmDS(t('m_q_delete',s))){deleteSlot(s);_mSfx('back');dsToast(t('m_deleted'));}if(o)o.refresh();}
