        R.push(_rBool('vibrate',()=>{if(SET.vibrate)vibrate(40);}));R.push(_rBool('mouseMove'));R.push(_rBool('mouseCam'));R.push(_rBool('invertZoom'));R.push(_rBool('camRelative'));
